<script>
 import { dimensionGridCounts } from '@/lib/formula-lessons/naive-dimension.mjs';
 export let lesson; export let spec;
 let resolution=spec.resolution; $: counts=dimensionGridCounts({resolution:Number(resolution),maxDimension:spec.maxDimension});
</script>
<div class="panel" data-dimension-growth-lesson data-focus={lesson.focus}><p class="eyebrow">Resolution per axis → required grid points</p><label>points per axis <output>{resolution}</output><input bind:value={resolution} type="range" min="2" max="10" step="1" /></label><div class="bars">{#each counts as row (row.dimension)}<div><span>{row.dimension}D</span><i style={`width:${Math.max(4,100*Math.log10(row.points)/Math.log10(counts.at(-1).points))}%`}></i><strong>{row.points.toLocaleString()}</strong></div>{/each}</div><p class="small">The source formula N_features &gt; N_observations is one high-dimensional warning. The grid shows the geometric companion: keeping the same per-axis resolution costs rᴺ samples.</p></div>
<style>.panel{border:1px solid var(--color-border);border-radius:1rem;background:var(--color-background);padding:1rem}.eyebrow{margin:0;font-size:.66rem;font-weight:900;text-transform:uppercase;letter-spacing:.1em;color:var(--color-muted-foreground)}label{display:grid;grid-template-columns:1fr auto;gap:.2rem;margin:.7rem 0;font-size:.73rem;font-weight:800}input{grid-column:1/-1;min-height:30px}.bars{display:grid;gap:.45rem}.bars div{display:grid;grid-template-columns:2rem 1fr 6rem;gap:.5rem;align-items:center;font-size:.72rem}.bars i{height:.8rem;border-radius:99px;background:var(--color-primary)}.bars strong{text-align:right}.small{margin:.8rem 0 0;font-size:.74rem;line-height:1.6;color:var(--color-muted-foreground)}@media(max-width:760px){.bars div{grid-template-columns:2rem 1fr 5rem}}
</style>
